"""
Transformation Rule: 
- Find all control points (cells with value 1, excluding the pattern row)
- Find the pattern in pattern_row: a contiguous non-zero sequence
- For each control point at (cr, cc), copy the pattern to row cr, starting at column (cc - 1)
- Always keep the original pattern at pattern_row
"""
from typing import List

def solve(grid: List[List[int]], pattern_row: int) -> List[List[int]]:
    rows, cols = len(grid), len(grid[0])
    output = [[0] * cols for _ in range(rows)]

    # Find the pattern in pattern_row
    pattern = []
    for c in range(cols):
        if grid[pattern_row][c] != 0:
            pattern.append((c, grid[pattern_row][c]))

    if not pattern:
        return output

    # Copy original pattern to output at pattern_row
    for (p_c, val) in pattern:
        output[pattern_row][p_c] = val

    # Find control points (1s not in pattern_row)
    control_points = []
    for r in range(rows):
        if r == pattern_row:
            continue
        for c in range(cols):
            if grid[r][c] == 1:
                control_points.append((r, c))

    # Pattern info
    pattern_start = pattern[0][0]
    pattern_end = pattern[-1][0]

    # For each control point, place pattern at (control_row, control_col - 1)
    for cr, cc in control_points:
        col_offset = cc - 1
        for offset, (p_c, val) in enumerate(pattern):
            col_dst = col_offset + offset
            if 0 <= col_dst < cols:
                output[cr][col_dst] = val

    return output

